<script>
  var OBRA_ID = {{ obra.id|tojson }};

  // --- ações de etapa (triagem/recortes/validacao) ---
  document.querySelectorAll('button[data-acao]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var acao = btn.getAttribute('data-acao');
      var res = document.getElementById('acao-resultado');
      btn.disabled = true;
      var body = {};
      var url = '/obras/' + OBRA_ID + '/' + acao;
      if (acao === 'validacao') {
        body = { classe: btn.getAttribute('data-classe'), n1_ok: true, n3_ok: true };
      } else if (acao === 'sa') {
        body = {};
      }
      fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      }).then(function (r) {
        if (!r.ok) throw new Error('http ' + r.status);
        return r.json();
      }).then(function () {
        res.className = 'faixa faixa-info';
        res.textContent = 'Etapa registrada. Atualizando…';
        setTimeout(function () { location.reload(); }, 900);
      }).catch(function () {
        res.className = 'faixa faixa-erro';
        res.setAttribute('role', 'alert');
        res.innerHTML = '<span aria-hidden="true">⚠</span> Não foi possível concluir. Tente de novo.';
        btn.disabled = false;
      });
    });
  });

  // --- ErrorMarker religado à API (§4). Chave estável mantida. ---
  (function () {
    var PAV = {{ (pavimento or 'GERAL')|tojson }};
    var CLASSE = {{ (classe_ativa or 'GERAL')|tojson }};
    var ITEM = {{ (item_id or 'ficha')|tojson }};
    var chave = ('aten_erro_' + CLASSE + '_' + OBRA_ID + '_' + PAV + '_' + ITEM)
      .replace(/ /g, '_');
    var chk = document.getElementById('erro_check');
    var txt = document.getElementById('erro_nota');
    var saved = document.getElementById('em_saved');
    var prov = document.getElementById('em_prov');
    var t = null;

    function save() {
      clearTimeout(t);
      t = setTimeout(function () {
        if (!chk.checked && !txt.value.trim()) return;
        fetch('/obras/' + OBRA_ID + '/comentarios', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            texto: (txt.value || '(marcada como errada, sem nota)'),
            tipo: chk.checked ? 'erro' : 'observacao',
            classe: CLASSE === 'GERAL' ? null : CLASSE,
            pavimento: PAV === 'GERAL' ? null : PAV,
            item_id: chave,
          }),
        }).then(function (r) {
          if (r.ok) {
            saved.hidden = false;
            return r.json();
          }
        }).then(function (j) {
          if (j) prov.textContent = 'marcado por ' + j.marcado_por;
        }).catch(function () { /* silencioso: autosave */ });
      }, 600);
    }
    chk.addEventListener('change', save);
    txt.addEventListener('input', save);
  })();
</script>
